import{validateRound,hints}from'./engine.mjs';const $=s=>document.querySelector(s);let selected;
try{const res=await fetch('./research-candidates.json');if(!res.ok)throw Error('Queue unavailable');const data=await res.json();for(const c of data.candidates){let b=document.createElement('button');b.textContent=c.title;let small=document.createElement('small');small.textContent=c.sponsor+' · pending audiovisual review';b.append(small);b.onclick=()=>{selected=c;document.querySelectorAll('#queue button').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#title').textContent=c.title;$('#answer').value=c.sponsor;$('#start').value='';$('#reveal').value='';$('#confirmed').checked=false;$('#evidence').value='';$('#review-status').textContent='';$('#windows').textContent='';$('#preview').replaceChildren();const iframe=document.createElement('iframe');iframe.src=`https://www.youtube-nocookie.com/embed/${c.videoId}?controls=1&start=${Math.floor(c.sponsorBlockSegments[0].segment[0])}`;iframe.title='Official candidate video — spoilers expected in editor';iframe.allow='encrypted-media; picture-in-picture';iframe.allowFullscreen=true;$('#preview').append(iframe);$('#watch').href=c.sourceUrl;$('#notes').textContent=`Research only: caption setup block ${c.setupWindow.join('–')}s; first brand block ${c.firstBrandMentionWindow.join('–')}s. SponsorBlock ad ${c.sponsorBlockSegments[0].segment.join('–')}s (${c.sponsorBlockSegments[0].votes} votes). These are not verified cutoffs. Check exact timings yourself.`;};$('#queue').append(b)}}catch(e){$('#title').textContent='Research queue unavailable';$('#notes').textContent=e.message}
function windows(){const start=Number($('#start').value),reveal=Number($('#reveal').value);$('#windows').textContent=reveal-start>=21?'Proposed hints: '+hints({start,reveal}).join(' / ')+' seconds. Review every window; 1-second reveal margin applied.':'A full 20-second setup plus the safety margin is required.'}$('#start').oninput=windows;$('#reveal').oninput=windows;
$('#review-form').onsubmit=e=>{e.preventDefault();try{if(!selected)throw Error('Select a candidate first.');const r={id:selected.videoId+'-'+Number($('#start').value).toFixed(1),kind:'youtube',title:$('#neutral-title').value.trim(),answer:$('#answer').value.trim(),videoId:selected.videoId,start:Number($('#start').value),reveal:Number($('#reveal').value),verified:true,visualSafe:true,reviewedBy:$('#reviewer').value.trim(),evidence:selected.sourceUrl+' | '+$('#evidence').value.trim(),aliases:[],hintDurations:[5,10,15,20],creativeId:selected.videoId+'-reviewed-setup',startAudit:{basis:'Reviewer-confirmed actual setup beginning',cue:$('#evidence').value.trim()}};validateRound(r);let existing=JSON.parse(localStorage.getItem('sg-rounds')||'[]');existing=existing.filter(x=>x.id!==r.id);existing.push(r);localStorage.setItem('sg-rounds',JSON.stringify(existing));const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify([r],null,2)],{type:'application/json'}));a.href=url;a.download=r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#review-status').textContent='Saved locally and exported. Return to the game and reload to play. The shared library changes only when a maintainer adds this reviewed JSON.';}catch(e){$('#review-status').textContent=e.message}};
